import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // 1. Stage Backdrop: Vertical engineered gradient to avoid empty void
  const bgGeo = new THREE.PlaneGeometry(8, 6);
  const bgMat = new MeshStandardNodeMaterial({
    roughness: 0.9,
    metalness: 0.1,
    color: 0x111116
  });
  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.z = -1.5;
  group.add(bgMesh);

  // Local Rim and Accent Lights for the product-shot look
  const localRimLight = new THREE.DirectionalLight('#ff2a38', 1.2);
  localRimLight.position.set(-3, 3, 2);
  group.add(localRimLight);

  const localKeyLight = new THREE.DirectionalLight('#e8ecf2', 1.4);
  localKeyLight.position.set(3, 4, 3);
  group.add(localKeyLight);

  // 2. Main Panel Container
  const panelWidth = 3.4;
  const panelHeight = 1.9;
  const panelGroup = new THREE.Group();
  group.add(panelGroup);

  // Panel Base Mesh (engineered gradient simulation using standard material)
  const panelGeo = new THREE.PlaneGeometry(panelWidth, panelHeight);
  const panelMat = new MeshStandardNodeMaterial({
    color: 0x14141a, // Vertical gradient mid-tone representation
    roughness: 0.6,
    metalness: 0.2,
    clearcoat: 0.1
  });
  const panelMesh = new THREE.Mesh(panelGeo, panelMat);
  panelGroup.add(panelMesh);

  // Hairline border
  const borderGeo = new THREE.EdgesGeometry(panelGeo);
  const borderMat = new THREE.LineBasicMaterial({ color: 0x26262f, linewidth: 1 });
  const borderMesh = new THREE.LineSegments(borderGeo, borderMat);
  borderMesh.position.z = 0.005;
  panelGroup.add(borderMesh);

  // 3. Typography & UI Content Elements
  const texts = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const quoteMarkItem = texts.find(t => t.role === 'quote-mark') || { text: '“' };
  const quoteItem = texts.find(t => t.role === 'quote') || { text: 'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.' };
  const attributionItem = texts.find(t => t.role === 'attribution') || { text: 'M. OKAFOR' };
  const captionItem = texts.find(t => t.role === 'caption') || { text: 'COLLECTOR SINCE 2019' };

  // Oversized Quote Mark (Extruded effect)
  const quoteMarkMesh = ctx.fontAtlas.createText(quoteMarkItem.text, {
    fontSize: 62,
    color: '#ff2a38',
    align: 'left'
  });
  // Positioned at top-left with padding (top ~0.5 units inside, left ~0.5 units inside)
  quoteMarkMesh.position.set(-panelWidth / 2 + 0.35, panelHeight / 2 - 0.45, 0.04);
  quoteMarkMesh.scale.setScalar(0.015); // Scale down font-atlas coordinate space to scene space
  panelGroup.add(quoteMarkMesh);

  // Client Quote (Floats +0.03 for raking light edge definition)
  const quoteMesh = ctx.fontAtlas.createText(quoteItem.text, {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'left',
    maxWidthPx: 160
  });
  quoteMesh.position.set(-panelWidth / 2 + 0.35, panelHeight / 2 - 0.85, 0.03);
  quoteMesh.scale.setScalar(0.015);
  panelGroup.add(quoteMesh);

  // Accent Rule below the quote
  const ruleGeo = new THREE.PlaneGeometry(0.2, 0.02);
  const ruleMat = new MeshStandardNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.4
  });
  const ruleMesh = new THREE.Mesh(ruleGeo, ruleMat);
  ruleMesh.position.set(-panelWidth / 2 + 0.45, panelHeight / 2 - 1.25, 0.02);
  panelGroup.add(ruleMesh);

  // Attribution Text
  const attributionMesh = ctx.fontAtlas.createText(attributionItem.text, {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 1
  });
  attributionMesh.position.set(-panelWidth / 2 + 0.35, panelHeight / 2 - 1.4, 0.03);
  attributionMesh.scale.setScalar(0.015);
  panelGroup.add(attributionMesh);

  // Caption Text
  const captionMesh = ctx.fontAtlas.createText(captionItem.text, {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 1.5
  });
  captionMesh.position.set(-panelWidth / 2 + 0.35, panelHeight / 2 - 1.55, 0.03);
  captionMesh.scale.setScalar(0.015);
  panelGroup.add(captionMesh);

  // 4. Entrance Motion Choreography
  const tl = gsap.timeline();

  // Initial states
  panelGroup.position.y = -0.2;
  panelGroup.scale.set(0.95, 0.95, 0.95);

  // Create a material opacity animation safe-proxy if needed, or simply translate & scale
  tl.to(panelGroup.position, {
    y: 0,
    duration: 0.5,
    ease: 'power2.out'
  });

  tl.to(panelGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.5,
    ease: 'power2.out'
  }, 0);

  // Settle effect on the quote mark
  quoteMarkMesh.scale.setScalar(0);
  tl.to(quoteMarkMesh.scale, {
    x: 0.015,
    y: 0.015,
    z: 0.015,
    duration: 0.9,
    ease: 'power4.out'
  }, 0.2);

  // 5. Cleanup Hook
  group.userData = {
    cleanup: () => {
      tl.kill();
      bgGeo.dispose();
      bgMat.dispose();
      panelGeo.dispose();
      panelMat.dispose();
      borderGeo.dispose();
      borderMat.dispose();
      ruleGeo.dispose();
      ruleMat.dispose();
    }
  };

  return group;
}
